// ──────────────────────────── tests ──────────────────────────────────────

test('tags null as "null", not "object"', () => {
  eq(typeOf(null), 'null');
  eq(typeof null, 'object'); // the lie you are fixing
});

test('tags arrays as "array"', () => {
  eq(typeOf([]), 'array');
  eq(typeOf([1, 2, 3]), 'array');
});

test('tags NaN as "nan" but keeps real numbers as "number"', () => {
  eq(typeOf(NaN), 'nan');
  eq(typeOf(0), 'number');
  eq(typeOf(Infinity), 'number');
});

test('passes through the honest typeof answers', () => {
  eq(typeOf('hi'), 'string');
  eq(typeOf(true), 'boolean');
  eq(typeOf(undefined), 'undefined');
  eq(typeOf(() => {}), 'function');
});

test('still says "object" for plain objects and dates', () => {
  eq(typeOf({}), 'object');
  eq(typeOf(new Date()), 'object');
});

test('knows symbols and bigints', () => {
  eq(typeOf(Symbol('id')), 'symbol');
  eq(typeOf(10n), 'bigint');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('tags the built-in object types', () => {
  eq(typeTag(new Date()), 'Date');
  eq(typeTag(new Map()), 'Map');
  eq(typeTag(new Set()), 'Set');
  eq(typeTag(/ab+/), 'RegExp');
});

test('tags null and undefined distinctly', () => {
  eq(typeTag(null), 'Null');
  eq(typeTag(undefined), 'Undefined');
});

test('tags primitives by their wrapper name', () => {
  eq(typeTag(1), 'Number');
  eq(typeTag(NaN), 'Number');
  eq(typeTag('hi'), 'String');
  eq(typeTag(false), 'Boolean');
});

test('separates arrays from functions from objects', () => {
  eq(typeTag([]), 'Array');
  eq(typeTag(() => {}), 'Function');
  eq(typeTag({}), 'Object');
});

test('isPlainObject accepts literals and null-prototype bags', () => {
  eq(isPlainObject({}), true);
  eq(isPlainObject({ a: 1 }), true);
  eq(isPlainObject(Object.create(null)), true);
});

test('isPlainObject rejects arrays, dates, null and class instances', () => {
  eq(isPlainObject([]), false);
  eq(isPlainObject(new Date()), false);
  eq(isPlainObject(new Map()), false);
  eq(isPlainObject(null), false);
  eq(isPlainObject(new Point(1)), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('0 == "" but 0 !== ""', () => {
  eq(equalityReport(0, ''), { loose: true, strict: false });
});

test('null is loosely equal to undefined and to nothing else', () => {
  eq(equalityReport(null, undefined), { loose: true, strict: false });
  eq(equalityReport(null, 0), { loose: false, strict: false });
  eq(equalityReport(undefined, false), { loose: false, strict: false });
});

test('NaN is not equal to itself under either operator', () => {
  eq(equalityReport(NaN, NaN), { loose: false, strict: false });
});

test('strings coerce to numbers before comparing', () => {
  eq(equalityReport('1', 1), { loose: true, strict: false });
  eq(equalityReport('0', false), { loose: true, strict: false });
  eq(equalityReport('abc', 0), { loose: false, strict: false });
});

test('objects compare by identity, but [] flattens to "" first', () => {
  const same = { id: 1 };
  eq(equalityReport(same, same), { loose: true, strict: true });
  eq(equalityReport({ id: 1 }, { id: 1 }), { loose: false, strict: false });
  eq(equalityReport([], ''), { loose: true, strict: false });
});

test('isNullish is true for exactly two values', () => {
  eq(isNullish(null), true);
  eq(isNullish(undefined), true);
  eq(isNullish(0), false);
  eq(isNullish(''), false);
  eq(isNullish(false), false);
  eq(isNullish(NaN), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('matches === for ordinary primitives', () => {
  eq(sameValue(1, 1), true);
  eq(sameValue('a', 'a'), true);
  eq(sameValue(true, true), true);
  eq(sameValue(1, 2), false);
});

test('NaN is the same value as NaN', () => {
  eq(sameValue(NaN, NaN), true);
  eq(sameValue(NaN, 0), false);
  eq(sameValue(0, NaN), false);
});

test('+0 and -0 are different values', () => {
  eq(sameValue(0, -0), false);
  eq(sameValue(-0, 0), false);
  eq(sameValue(-0, -0), true);
  eq(sameValue(0, 0), true);
});

test('null and undefined are each only themselves', () => {
  eq(sameValue(null, null), true);
  eq(sameValue(undefined, undefined), true);
  eq(sameValue(null, undefined), false);
});

test('never coerces', () => {
  eq(sameValue(1, '1'), false);
  eq(sameValue(0, false), false);
  eq(sameValue('', false), false);
  eq(sameValue(null, 0), false);
});

test('objects are compared by reference', () => {
  const box = { n: 1 };
  const list = [1];
  eq(sameValue(box, box), true);
  eq(sameValue(list, list), true);
  eq(sameValue({ n: 1 }, { n: 1 }), false);
});

test('agrees with the real Object.is on a whole table', () => {
  const pairs = [
    [NaN, NaN],
    [0, -0],
    [-0, 0],
    [1, 1],
    ['x', 'x'],
    [null, undefined],
    [Infinity, Infinity],
    [Infinity, -Infinity],
  ];
  for (const [a, b] of pairs) {
    const label = `${String(a)} vs ${String(b)}`;
    ok(sameValue(a, b) === Object.is(a, b), `mismatch for ${label}`);
  }
});

// ──────────────────────────── tests ──────────────────────────────────────

test('counts nothing in the eight falsy values', () => {
  eq(countTruthy([false, 0, -0, 0n, '', null, undefined, NaN]), 0);
});

test('counts the sneaky truthy ones', () => {
  eq(countTruthy(['0', 'false', [], {}, ' ', -1, Infinity]), 7);
});

test('counts a mixed list', () => {
  eq(countTruthy([1, null, 'x', 0, [], '']), 3);
});

test('an empty list has nothing truthy', () => {
  eq(countTruthy([]), 0);
  eq(firstTruthy([]), undefined);
});

test('firstTruthy skips the falsy prefix', () => {
  eq(firstTruthy([0, '', null, 'found', 'later']), 'found');
  eq(firstTruthy([NaN, 42]), 42);
});

test('firstTruthy can return an empty array, which is truthy', () => {
  eq(firstTruthy([0, [], 'x']), []);
});

test('firstTruthy returns undefined when everything is falsy', () => {
  eq(firstTruthy([0, '', null, undefined, NaN]), undefined);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('null and undefined are empty', () => {
  eq(isEmpty(null), true);
  eq(isEmpty(undefined), true);
});

test('whitespace-only strings count as empty', () => {
  eq(isEmpty(''), true);
  eq(isEmpty('   '), true);
  eq(isEmpty('\n\t'), true);
  eq(isEmpty('a'), false);
  eq(isEmpty('0'), false);
});

test('arrays go by length, not by content', () => {
  eq(isEmpty([]), true);
  eq(isEmpty([undefined]), false);
  eq(isEmpty([0]), false);
});

test('objects go by their own enumerable keys', () => {
  eq(isEmpty({}), true);
  eq(isEmpty({ a: undefined }), false);
  eq(isEmpty({ a: 1 }), false);
});

test('Map and Set go by size', () => {
  eq(isEmpty(new Map()), true);
  eq(isEmpty(new Set()), true);
  eq(isEmpty(new Map([['k', 'v']])), false);
  eq(isEmpty(new Set([0])), false);
});

test('numbers and booleans are never empty', () => {
  eq(isEmpty(0), false);
  eq(isEmpty(-0), false);
  eq(isEmpty(NaN), false);
  eq(isEmpty(false), false);
  eq(isEmpty(0n), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('fills in every default when nothing is provided', () => {
  eq(withDefaults({}), {
    volume: 50,
    label: 'untitled',
    retries: 3,
    verbose: false,
  });
});

test('keeps an explicit 0 — the classic || bug', () => {
  eq(withDefaults({ volume: 0 }).volume, 0);
});

test('keeps an explicit empty string and an explicit false', () => {
  eq(withDefaults({ label: '' }).label, '');
  eq(withDefaults({ verbose: false }).verbose, false);
});

test('null and undefined both mean "use the default"', () => {
  eq(withDefaults({ retries: null }).retries, 3);
  eq(withDefaults({ retries: undefined }).retries, 3);
});

test('returns a fresh object and mutates nothing', () => {
  const input = Object.freeze({ volume: 11 });
  const result = withDefaults(input);
  ok(result !== input, 'should not hand back the input object');
  ok(result !== DEFAULTS, 'should not hand back DEFAULTS');
  eq(input, { volume: 11 });
  eq(DEFAULTS.volume, 50);
});

test('drops keys that are not part of the settings shape', () => {
  eq(withDefaults({ nope: 1, volume: 7 }), {
    volume: 7,
    label: 'untitled',
    retries: 3,
    verbose: false,
  });
});

test('orDefault falls back only for null and undefined', () => {
  eq(orDefault(0, 9), 0);
  eq(orDefault('', 'x'), '');
  eq(orDefault(false, true), false);
  eq(orDefault(null, 9), 9);
  eq(orDefault(undefined, 9), 9);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('safeCall runs fn when the guard is truthy', () => {
  const fn = spy(() => 'ran');
  eq(safeCall(1, fn), 'ran');
  eq(fn.callCount, 1);
});

test('safeCall returns the guard itself, not false', () => {
  const fn = () => 'ran';
  eq(safeCall(0, fn), 0);
  eq(safeCall('', fn), '');
  eq(safeCall(null, fn), null);
  eq(safeCall(undefined, fn), undefined);
});

test('safeCall never calls fn when the guard is falsy', () => {
  const fn = spy(() => 'ran');
  safeCall(0, fn);
  safeCall('', fn);
  safeCall(NaN, fn);
  eq(fn.callCount, 0);
});

test('safeCall passes through whatever fn returns, even falsy', () => {
  eq(safeCall(true, () => 0), 0);
  eq(safeCall('yes', () => null), null);
});

test('lazyDefault keeps 0, "" and false', () => {
  eq(lazyDefault(0, () => 'x'), 0);
  eq(lazyDefault('', () => 'x'), '');
  eq(lazyDefault(false, () => 'x'), false);
});

test('lazyDefault does not build a default it does not need', () => {
  const make = spy(() => 'x');
  lazyDefault(0, make);
  lazyDefault('', make);
  lazyDefault(false, make);
  eq(make.callCount, 0);
});

test('lazyDefault builds the default exactly once for nullish input', () => {
  const make = spy(() => 'built');
  eq(lazyDefault(null, make), 'built');
  eq(make.callCount, 1);
  eq(lazyDefault(undefined, make), 'built');
  eq(make.callCount, 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('forgives the classic 0.1 + 0.2 drift', () => {
  eq(nearlyEqual(0.1 + 0.2, 0.3), true);
  ok(0.1 + 0.2 !== 0.3, 'the raw comparison really is false');
});

test('identical numbers are nearly equal', () => {
  eq(nearlyEqual(1, 1), true);
  eq(nearlyEqual(0, 0), true);
  eq(nearlyEqual(-5.5, -5.5), true);
});

test('genuinely different numbers are not', () => {
  eq(nearlyEqual(0.1, 0.2), false);
  eq(nearlyEqual(1, 1.0001), false);
});

test('the tolerance scales with magnitude', () => {
  eq(nearlyEqual(100, 100.5, 0.006), true);
  eq(nearlyEqual(100, 100.5, 0.004), false);
});

test('the scale never drops below 1, so small numbers still work', () => {
  eq(nearlyEqual(0, 0.005, 0.006), true);
  eq(nearlyEqual(0, 0.5, 0.006), false);
});

test('NaN is nearly equal to nothing, itself included', () => {
  eq(nearlyEqual(NaN, NaN), false);
  eq(nearlyEqual(NaN, 1), false);
});

test('Infinity equals itself but beats every finite number', () => {
  eq(nearlyEqual(Infinity, Infinity), true);
  eq(nearlyEqual(Infinity, 1e308), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('rounds to the requested number of decimals', () => {
  eq(roundTo(1.234, 2), 1.23);
  eq(roundTo(2.345, 2), 2.35);
  eq(roundTo(1 / 3, 4), 0.3333);
});

test('beats the 1.005 trap', () => {
  eq(roundTo(1.005, 2), 1.01);
  eq(roundTo(2.675, 2), 2.68);
});

test('cleans up float dust', () => {
  eq(roundTo(0.1 + 0.2, 2), 0.3);
  eq(roundTo(0.1 + 0.7, 1), 0.8);
});

test('digits defaults to 0', () => {
  eq(roundTo(2.5), 3);
  eq(roundTo(2.4), 2);
  eq(roundTo(7), 7);
});

test('rounds halves away from zero, not toward +Infinity', () => {
  eq(roundTo(-2.5), -3);
  eq(roundTo(-1.005, 2), -1.01);
  eq(roundTo(-0.125, 2), -0.13);
});

test('leaves already-round values alone', () => {
  eq(roundTo(5, 2), 5);
  eq(roundTo(0, 2), 0);
  eq(roundTo(-4, 3), -4);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('parses ordinary numeric strings', () => {
  eq(toNumber('42'), 42);
  eq(toNumber('-3.5'), -3.5);
  eq(toNumber('0'), 0);
});

test('accepts real numbers unchanged and tolerates whitespace', () => {
  eq(toNumber(0), 0);
  eq(toNumber(-7.25), -7.25);
  eq(toNumber('  7  '), 7);
});

test('rejects the strings parseInt would half-eat', () => {
  eq(toNumber('42px'), null);
  eq(toNumber('3 apples'), null);
  eq(parseInt('42px'), 42); // proof of the thing you are avoiding
});

test('rejects the values Number() quietly turns into 0', () => {
  eq(toNumber(''), null);
  eq(toNumber('   '), null);
  eq(toNumber(null), null);
  eq(toNumber([]), null);
  eq(Number(''), 0); // proof again
});

test('rejects anything that is not finite', () => {
  eq(toNumber(NaN), null);
  eq(toNumber(Infinity), null);
  eq(toNumber('1e999'), null);
});

test('rejects booleans, undefined and objects', () => {
  eq(toNumber(true), null);
  eq(toNumber(false), null);
  eq(toNumber(undefined), null);
  eq(toNumber({}), null);
});

test('understands exponent and hex notation, like Number does', () => {
  eq(toNumber('1e3'), 1000);
  eq(toNumber('0x1f'), 31);
});

test('toSafeInt demands a whole number inside the safe range', () => {
  eq(toSafeInt('42'), 42);
  eq(toSafeInt(-9), -9);
  eq(toSafeInt('4.5'), null);
  eq(toSafeInt(Number.MAX_SAFE_INTEGER), 9007199254740991);
  eq(toSafeInt(2 ** 53), null);
  eq(toSafeInt('9007199254740993'), null);
});

// ──────────────────────────── tests ──────────────────────────────────────

const ORDER = {
  id: 7,
  items: [
    { name: 'Tea', qty: 2 },
    { name: 'Scone', qty: 1 },
  ],
};

test('badge interpolates both fields', () => {
  eq(badge({ name: 'Ada', email: 'ada@x.io' }), 'Ada <ada@x.io>');
  eq(badge({ name: 'Bo', email: 'bo@y.io' }), 'Bo <bo@y.io>');
});

test('the receipt starts with the order header', () => {
  ok(receipt(ORDER).startsWith('Order #7'));
});

test('the receipt renders one line per item', () => {
  eq(receipt(ORDER), 'Order #7\nTea x2\nScone x1\ntotal: 3 items');
});

test('lines are separated by newlines, not spaces', () => {
  eq(receipt(ORDER).split('\n').length, 4);
  ok(!receipt(ORDER).endsWith('\n'), 'no trailing newline');
});

test('the total sums the quantities, not the line count', () => {
  const bulk = { id: 1, items: [{ name: 'Bean', qty: 40 }] };
  eq(receipt(bulk), 'Order #1\nBean x40\ntotal: 40 items');
});

test('an empty order says (empty)', () => {
  eq(receipt({ id: 3, items: [] }), 'Order #3\n(empty)\ntotal: 0 items');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns the static text when there is nothing to interpolate', () => {
  eq(html`plain text`, 'plain text');
  eq(html``, '');
});

test('interpolates ordinary values', () => {
  eq(html`<p>${'hi'}</p>`, '<p>hi</p>');
  eq(html`n=${42}`, 'n=42');
  eq(html`${true}`, 'true');
});

test('escapes HTML in the values', () => {
  eq(html`<p>${'<b>hi</b>'}</p>`, '<p>&lt;b&gt;hi&lt;/b&gt;</p>');
  eq(html`${'<script>'}`, '&lt;script&gt;');
});

test('never escapes the static parts', () => {
  eq(html`a & b`, 'a & b');
  eq(html`<div>${'x'}</div>`, '<div>x</div>');
});

test('escapes quotes and ampersands too', () => {
  eq(html`${'Tom & "Jerry"'}`, 'Tom &amp; &quot;Jerry&quot;');
  eq(html`${"it's"}`, 'it&#39;s');
});

test('renders null and undefined as nothing', () => {
  eq(html`<i>${null}</i>`, '<i></i>');
  eq(html`<i>${undefined}</i>`, '<i></i>');
  eq(html`${0}`, '0');
});

test('joins array values, escaping each item', () => {
  eq(html`<ul>${['<a>', 'b']}</ul>`, '<ul>&lt;a&gt;b</ul>');
  eq(html`${[]}`, '');
});

test('handles several substitutions in a row', () => {
  eq(html`${1}${2}${3}`, '123');
  eq(html`${'a'}-${'b'}-`, 'a-b-');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a var read before its line is undefined, not an error', () => {
  eq(varProbe()[0], undefined);
});

test('the var still gets its value once the line runs', () => {
  eq(varProbe(), [undefined, 5]);
});

test('a let read inside its TDZ throws a ReferenceError', () => {
  eq(letProbe()[0], 'ReferenceError');
});

test('the same let is perfectly usable after its line', () => {
  eq(letProbe(), ['ReferenceError', 5]);
});

test('var ignores the block — the inner assignment escapes', () => {
  eq(blockScope().fromVar, 'inner');
});

test('let creates a separate binding inside the block', () => {
  eq(blockScope().fromLet, 'outer');
  eq(blockScope(), { fromVar: 'inner', fromLet: 'outer' });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('captureIndexes returns one function per item', () => {
  const fns = captureIndexes(['a', 'b', 'c']);
  eq(fns.length, 3);
  ok(typeof fns[0] === 'function');
});

test('each captured function reports its own index', () => {
  eq(
    captureIndexes(['a', 'b', 'c']).map((f) => f()),
    [0, 1, 2]
  );
});

test('the last index is not smeared over all of them', () => {
  const fns = captureIndexes([10, 20, 30, 40]);
  eq(fns[0](), 0);
  eq(fns[3](), 3);
});

test('an empty list produces no functions', () => {
  eq(captureIndexes([]), []);
  eq(makeCounters(0), []);
});

test('a counter starts at 1 and keeps climbing', () => {
  const [tick] = makeCounters(1);
  eq(tick(), 1);
  eq(tick(), 2);
  eq(tick(), 3);
});

test('counters do not share state', () => {
  const [first, second] = makeCounters(2);
  first();
  first();
  eq(second(), 1);
  eq(first(), 3);
});

test('each call to makeCounters starts a fresh set', () => {
  const [a] = makeCounters(1);
  a();
  a();
  const [b] = makeCounters(1);
  eq(b(), 1);
  eq(a(), 3);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('firstTwo names the first two slots', () => {
  eq(firstTwo([10, 20, 30]), { first: 10, second: 20 });
  eq(firstTwo(['a', 'b']), { first: 'a', second: 'b' });
});

test('a missing slot is undefined, not an error', () => {
  eq(firstTwo(['solo']), { first: 'solo', second: undefined });
  eq(firstTwo([]), { first: undefined, second: undefined });
});

test('swap flips a pair', () => {
  eq(swap([1, 2]), [2, 1]);
  eq(swap(['x', null]), [null, 'x']);
});

test('swap leaves the original array alone', () => {
  const pair = Object.freeze([1, 2]);
  eq(swap(pair), [2, 1]);
  eq(pair, [1, 2]);
});

test('thirdOr reaches past the first two slots', () => {
  eq(thirdOr([1, 2, 9], '-'), 9);
  eq(thirdOr([1, 2, 3, 4], '-'), 3);
});

test('thirdOr falls back only when the slot is undefined', () => {
  eq(thirdOr([1, 2], '-'), '-');
  eq(thirdOr([], '-'), '-');
  eq(thirdOr([1, 2, undefined], '-'), '-');
  eq(thirdOr([1, 2, null], '-'), null);
  eq(thirdOr([1, 2, 0], '-'), 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('renames id to userId', () => {
  eq(parseUser({ id: 7 }).userId, 7);
  eq(parseUser({ id: 'abc' }).userId, 'abc');
});

test('reads the nested profile fields', () => {
  eq(parseUser({ id: 1, profile: { name: 'Ada', city: 'London' } }), {
    userId: 1,
    name: 'Ada',
    city: 'London',
    tagCount: 0,
  });
});

test('a missing profile still yields both defaults', () => {
  eq(parseUser({ id: 2 }), {
    userId: 2,
    name: 'anonymous',
    city: 'unknown',
    tagCount: 0,
  });
});

test('defaults apply field by field', () => {
  eq(parseUser({ id: 3, profile: { name: 'Bo' } }).city, 'unknown');
  eq(parseUser({ id: 3, profile: { city: 'Oslo' } }).name, 'anonymous');
});

test('an explicit null is kept — defaults only replace undefined', () => {
  eq(parseUser({ id: 4, profile: { name: null } }).name, null);
  eq(parseUser({ id: 4, profile: { name: undefined } }).name, 'anonymous');
  eq(parseUser({ id: 4, profile: { city: '' } }).city, '');
});

test('tagCount counts the tags, defaulting to an empty list', () => {
  eq(parseUser({ id: 5, tags: ['a', 'b', 'c'] }).tagCount, 3);
  eq(parseUser({ id: 5, tags: [] }).tagCount, 0);
  eq(parseUser({ id: 5 }).tagCount, 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('fills in the method and headers defaults', () => {
  eq(createRequest({ url: '/a' }), {
    url: '/a',
    method: 'GET',
    headers: {},
    extras: {},
  });
});

test('survives being called with no argument at all', () => {
  eq(createRequest(), {
    url: undefined,
    method: 'GET',
    headers: {},
    extras: {},
  });
});

test('keeps the values that were provided', () => {
  const headers = { accept: 'json' };
  const result = createRequest({ url: '/b', method: 'POST', headers });
  eq(result.method, 'POST');
  eq(result.headers, { accept: 'json' });
  ok(result.headers === headers, 'headers is passed through, not copied');
});

test('collects unknown options into extras', () => {
  eq(createRequest({ url: '/c', retries: 2, timeout: 50 }).extras, {
    retries: 2,
    timeout: 50,
  });
});

test('the named options never leak into extras', () => {
  const result = createRequest({ url: '/d', method: 'PUT', headers: {} });
  eq(Object.keys(result.extras), []);
});

test('an explicit undefined takes the default, null does not', () => {
  eq(createRequest({ method: undefined }).method, 'GET');
  eq(createRequest({ method: null }).method, null);
  eq(createRequest({ headers: null }).headers, null);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('copyList returns an equal but different array', () => {
  const original = [1, 2, 3];
  const copy = copyList(original);
  eq(copy, [1, 2, 3]);
