  eq(sumCleanRows(GRID), 45);
  eq(sumCleanRows([[1, 2, -3], [10]]), 10);
});

test('sumCleanRows copes with empty rows and an empty grid', () => {
  eq(sumCleanRows([]), 0);
  eq(sumCleanRows([[]]), 0);
  eq(sumCleanRows([[-1]]), 0);
  eq(sumCleanRows([[], [5]]), 5);
});

