//
//      cartTotal([{ price: '12.34', qty: 2 }, { price: '0.99' }])  → 2567
//      cartTotal([{ price: '12.34', qty: 2 }, { price: '0.99' }], 8.25)
//      → 2779         (2567 + round(2567 × 8.25 / 100) = 2567 + 212)
