  eq(makeLabel('api', 'svc', { sep: '/' }), 'svc/api');
  eq(makeLabel('api', 'svc', {}), 'svc:api');
  eq(makeLabel('api', 'svc', undefined), 'svc:api');
  eq(makeLabel('api', undefined, { sep: '.' }), 'API.api');
