const MODULE_SECRET = 'not-global';
let issued = 0;

export function hasGlobal(name) {
  throw new Error('TODO');
}

export function withGlobal(name, value, fn) {
  throw new Error('TODO');
}

export function nextTicket() {
  throw new Error('TODO');
}

